CREATE POLICY "Own recitation files read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'recitations' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own recitation files insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'recitations' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own recitation files delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'recitations' AND (storage.foldername(name))[1] = auth.uid()::text);